1	import { Fragment, useState } from "react";
2	import EnchantingColumn from "@/components/game/EnchantingColumn";
3	import ItemIcon from "@/components/game/ItemIcon";
4	import { itemTooltipFor, type TooltipContent, useItemTooltip } from "@/components/game/ItemTooltip";
5	import PixelImg from "@/components/game/PixelImg";
6	import { CONTAINER_SLOT_BASE } from "@/lib/game/engine/commands";
7	import { ingredientStatus } from "@/lib/game/inventory";
8	import { itemSourceHint } from "@/lib/game/itemSources";
9	import { ARMOR_SLOT_LABELS, ARMOR_SLOTS, createSlot, ITEM_DEF_BY_ID } from "@/lib/game/items";
10	import { groupRecipes } from "@/lib/game/recipes";
11	import { itemIconUrl } from "@/lib/ui/sprites";
12	import type { EnchantmentId, EquippedArmor, InventorySlot, Recipe } from "@/lib/game/types";
13	
14	type InventoryPanelProps = {
15	  inventory: InventorySlot[];
16	  equippedArmor: EquippedArmor;
17	  selectedHotbarSlot: number;
18	  hotbarSlots: number;
19	  recipes: Recipe[];
20	  craftingStation: "furnace" | "villager" | "brewing" | "enchanting" | null;
21	  /** Contents of the open chest, or null when no chest is open. */
22	  container: InventorySlot[] | null;
23	  /** Current XP level + per-enchant cost, for the enchanting panel. */
24	  xpLevel: number;
25	  enchantCost: number;
26	  canCraft: (recipe: Recipe) => boolean;
27	  onSwapSlots: (fromIndex: number, toIndex: number) => void;
28	  /** Moves a slot across the inventory/chest boundary (chest indices offset by CONTAINER_SLOT_BASE). */
29	  onMoveStack: (fromIndex: number, toIndex: number) => void;
30	  onToggleEquipArmor: (index: number) => void;
31	  onCraft: (recipe: Recipe) => void;
32	  onEnchant: (id: EnchantmentId) => void;
33	};
34	
35	const STATION_LABELS: Record<NonNullable<Recipe["station"]>, string> = {
36	  furnace: "Furnace",
37	  villager: "Villager",
38	  brewing: "Brewing Stand"
39	};
40	
41	const labelFor = (slotId: string): string => ITEM_DEF_BY_ID[slotId]?.label ?? slotId;
42	
43	/**
44	 * Hover text for a recipe. A craftable recipe just names itself; a station-locked
45	 * one says which station it needs; an unaffordable one lists each ingredient as
46	 * have/need and, for every shortfall, a "how to obtain" hint. The detail is what
47	 * the user can't read from the tiny grayscale icons alone.
48	 */
49	function recipeTooltip(recipe: Recipe, inventory: InventorySlot[], locked: boolean, craftable: boolean): TooltipContent {
50	  if (locked) return { title: labelFor(recipe.result.slotId), lines: [`Requires ${STATION_LABELS[recipe.station!]}`] };
51	  if (craftable) return { title: recipe.label };
52	
53	  const status = ingredientStatus(inventory, recipe);
54	  const lines = status.map((s) => `${labelFor(s.slotId)}  ${s.have} / ${s.need}${s.have < s.need ? ` (need ${s.need - s.have} more)` : " ✓"}`);
55	  for (const s of status) {
56	    if (s.have >= s.need) continue;
57	    const hint = itemSourceHint(s.slotId);
58	    if (hint) lines.push(`→ ${labelFor(s.slotId)}: ${hint}`);
59	  }
60	  return { title: labelFor(recipe.result.slotId), lines };
61	}
62	
63	/**
64	 * The survival inventory: armor column, 27-slot storage grid, hotbar row, and
65	 * a recipe book where every entry shows ingredient icons and the result.
66	 * Items move by clicking one slot and then another (click-to-swap); clicking
67	 * an armor item toggles equipping it instead.
68	 */
69	export default function InventoryPanel({
70	  inventory,
71	  equippedArmor,
72	  selectedHotbarSlot,
73	  hotbarSlots,
74	  recipes,
75	  craftingStation,
76	  container,
77	  xpLevel,
78	  enchantCost,
79	  canCraft,
80	  onSwapSlots,
81	  onMoveStack,
82	  onToggleEquipArmor,
83	  onCraft,
84	  onEnchant
85	}: InventoryPanelProps) {
86	  const [pendingIndex, setPendingIndex] = useState<number | null>(null);
87	  const { tooltip, bind } = useItemTooltip();
88	
89	  // While a chest is open, moves span both grids (chest slots are offset by
90	  // CONTAINER_SLOT_BASE); otherwise a swap stays within the player inventory.
91	  const slotAt = (index: number): InventorySlot | undefined => (index >= CONTAINER_SLOT_BASE ? container?.[index - CONTAINER_SLOT_BASE] : inventory[index]);
92	
93	  const onSlotClick = (index: number) => {
94	    const slot = slotAt(index);
95	    if (!slot) return;
96	    // Clicking armor in the player inventory equips it; chest slots only move.
97	    if (index < CONTAINER_SLOT_BASE && slot.kind === "armor" && slot.count > 0) {
98	      onToggleEquipArmor(index);
99	      setPendingIndex(null);
100	      return;
101	    }
102	
103	    if (pendingIndex === null) {
104	      setPendingIndex(index);
105	      return;
106	    }
107	    if (pendingIndex === index) {
108	      setPendingIndex(null);
109	      return;
110	    }
111	    (container ? onMoveStack : onSwapSlots)(pendingIndex, index);
112	    setPendingIndex(null);
