27	    const q = query.trim().toLowerCase();
28	    const matches = ITEM_DEFS.filter((def) => !q || def.label.toLowerCase().includes(q) || def.id.includes(q));
29	    return KIND_SECTIONS.map((section) => ({ ...section, items: matches.filter((def) => def.kind === section.kind) })).filter(
30	      (section) => section.items.length > 0
31	    );
32	  }, [query]);
33	
34	  return (
35	    <div className="recipe-book creative-palette">
36	      <div className="inventory-heading">Creative</div>
37	      <input
38	        className="creative-search"
39	        type="text"
...
44	        {groups.length === 0 ? <div className="creative-empty">No items match “{query}”.</div> : null}
45	        {groups.map((group) => (
46	          <Fragment key={group.kind}>
47	            <div className="recipe-category" role="presentation">
48	              {group.label}
49	            </div>
50	            <div className="inv-grid creative-grid" data-testid={`creative-${group.kind}`}>
51	              {group.items.map((def) => (
52	                <button
53	                  key={def.id}
54	                  className="inv-slot"
55	                  onClick={() => onGiveItem(def.id)}
56	                  {...bind(itemTooltipFor(createSlot(def.id, 1)))}
57	                  aria-label={`Give ${def.label}`}
58	                >
59	                  <ItemIcon slot={createSlot(def.id, 1)} size={32} />
60	                </button>
61	              ))}
62	            </div>
63	          </Fragment>
64	        ))}
65	      </div>
66	      {tooltip}

