import { describe, expect, test } from "bun:test";
import * as THREE from "three";
import { createPlayerVisuals, type PlayerVisualsState } from "@/lib/game/render/playerVisuals";
import { createEmptySlot, createSlot } from "@/lib/game/items";
import { getSkinPreset } from "@/lib/game/playerSkins";

function makeState(overrides: Partial<PlayerVisualsState> = {}): PlayerVisualsState {
  return {
    cameraMode: "third-rear",
    isDead: false,
    player: {
      position: new THREE.Vector3(10, 20, 30),
      velocity: new THREE.Vector3(),
      yaw: 0.7,
      pitch: -0.2,
      onGround: true
    },
    inventory: [createSlot("dirt", 5)],
    selectedSlot: 0,
    mining: { targetKey: "" },
    fishing: null,
    ...overrides
  };
}

function bodyGroup(scene: THREE.Scene): THREE.Group {
  return scene.children[0] as THREE.Group;
}

describe("playerVisuals", () => {
  test("hidden in first person, visible in both third-person modes", () => {
    const scene = new THREE.Scene();
    const visuals = createPlayerVisuals(scene);
    const group = bodyGroup(scene);

    visuals.sync(makeState({ cameraMode: "first" }), 0);
    expect(group.visible).toBe(false);
    visuals.sync(makeState({ cameraMode: "third-rear" }), 0);
    expect(group.visible).toBe(true);
    visuals.sync(makeState({ cameraMode: "third-front" }), 0);
    expect(group.visible).toBe(true);
    visuals.dispose();
  });

  test("hidden while dead so the corpse never floats behind the death screen", () => {
    const scene = new THREE.Scene();
    const visuals = createPlayerVisuals(scene);
    visuals.sync(makeState({ isDead: true }), 0);
    expect(bodyGroup(scene).visible).toBe(false);
    visuals.dispose();
  });

  test("follows the player's feet position and yaw, pitch only tilts the head", () => {
    const scene = new THREE.Scene();
    const visuals = createPlayerVisuals(scene);
    const state = makeState();
    visuals.sync(state, 0);

    const group = bodyGroup(scene);
    expect(group.position.toArray()).toEqual([10, 20, 30]);
    expect(group.rotation.y).toBeCloseTo(0.7);
    expect(group.rotation.x).toBe(0);
    const head = group.getObjectByName("head")!;
    expect(head.rotation.x).toBeCloseTo(-0.2);
    visuals.dispose();
  });

  test("rebuilds the hand item when the selected slot changes", () => {
    const scene = new THREE.Scene();
    const visuals = createPlayerVisuals(scene);

    const holderChildren = () => bodyGroup(scene).getObjectByName("itemHolder")!.children.length;

    visuals.sync(makeState({ inventory: [createSlot("dirt", 5)] }), 0);
    expect(holderChildren()).toBe(1);
    visuals.sync(makeState({ inventory: [createSlot("wood_pickaxe", 1)] }), 16);
    expect(holderChildren()).toBe(1);
    visuals.sync(makeState({ inventory: [createEmptySlot()] }), 32);
    expect(holderChildren()).toBe(0);
    visuals.dispose();
  });

  test("a queued swing fires on the next visible sync, not after re-show", () => {
    const scene = new THREE.Scene();
    const visuals = createPlayerVisuals(scene);
    const group = bodyGroup(scene);
    const rightArm = group.getObjectByName("rightArm")!;

    // Swing queued while hidden is dropped.
    visuals.triggerSwing();
    visuals.sync(makeState({ cameraMode: "first" }), 0);
    visuals.sync(makeState(), 130);
    expect(rightArm.rotation.x).toBe(0);

    // Swing queued while visible animates the arm at mid-swing.
    visuals.triggerSwing();
    visuals.sync(makeState(), 1000);
    visuals.sync(makeState(), 1130);
    expect(rightArm.rotation.x).toBeLessThan(-1);
    visuals.dispose();
  });

  test("setPalette recolors the visible body live", () => {
    const scene = new THREE.Scene();
    const visuals = createPlayerVisuals(scene);
    visuals.sync(makeState(), 0);

    const knight = getSkinPreset("knight").palette;
    visuals.setPalette(knight);

    const head = bodyGroup(scene).getObjectByName("head")!;
    const skull = head.children[0] as THREE.Mesh;
    expect((skull.material as THREE.MeshStandardMaterial).color.getHex()).toBe(knight.skin);
    visuals.dispose();
  });

  test("dispose removes the body from the scene", () => {
    const scene = new THREE.Scene();
    const visuals = createPlayerVisuals(scene);
    visuals.dispose();
    expect(scene.children).toHaveLength(0);
  });
});

"use client";

import { useEffect } from "react";
import ActiveEffects from "@/components/game/ActiveEffects";
import BossHealthBar from "@/components/game/BossHealthBar";
import DeathScreen from "@/components/game/DeathScreen";
import DebugOverlay from "@/components/game/DebugOverlay";
import Hotbar from "@/components/game/Hotbar";
import InventoryPanel from "@/components/game/InventoryPanel";
import PauseMenu from "@/components/game/PauseMenu";
import SleepOverlay from "@/components/game/SleepOverlay";
import StatusBars from "@/components/game/StatusBars";
import VictoryScreen from "@/components/game/VictoryScreen";
import XpBar from "@/components/game/XpBar";
import { ENCHANT_COST_LEVELS } from "@/lib/game/config";
import type { Profile } from "@/lib/game/profiles";
import { useMinecraftGame } from "@/lib/game/useMinecraftGame";
import type { WorldMeta } from "@/lib/game/worlds";
import { installUiTiles } from "@/lib/ui/chromeTiles";

type MinecraftGameProps = {
  world: WorldMeta;
  profile: Profile;
  onQuitToWorlds: () => void;
  onReloadWorld: () => void;
};

export default function MinecraftGame({ world, profile, onQuitToWorlds, onReloadWorld }: MinecraftGameProps) {
  const {
    attachMount,
    attachMinimap,
    locked,
    rendererError,
    gameMode,
    giveCreativeItem,
    selectedSlot,
    setSelectedSlot,
    capsActive,
    inventoryOpen,
    inventory,
    equippedArmor,
    armorPoints,
    hearts,
    hunger,
    oxygen,
    daylightPercent,
    passiveCount,
    hostileCount,
    respawnSeconds,
    paused,
    sleeping,
    craftingStation,
    container,
    boss,
    victory,
    activeEffects,
    xpLevel,
    xpProgress,
    debugOpen,
    debug,
    saveMessage,
    audioSettings,
    updateAudioSettings,
    skinId,
    updateSkin,
    hotbarSlots,
    recipes,
    maxHearts,
    maxHunger,
    maxOxygen,
    canCraft,
    craft,
    enchant,
    swapInventorySlots,
    moveStack,
    toggleEquipArmor,
    resumeNow,
    respawnNow,
    dismissVictory,
    saveNow,
    loadNow,
    resetNow,
    quitToWorlds
  } = useMinecraftGame({ world, profile, onQuitToWorlds, onReloadWorld });

  useEffect(() => {
    installUiTiles();
  }, []);

  if (rendererError) {
    return (
      <div className="game-root">
        <div className="renderer-error">
          <h2>Could not start the 3D renderer</h2>
          <p>WebGL appears to be unavailable in this browser ({rendererError}).</p>
          <p>Try enabling hardware acceleration or switching browsers, then reload.</p>
        </div>
      </div>
    );
  }

  const showClickHint = !locked && !paused && !inventoryOpen && respawnSeconds === 0;

  return (
    <div className="game-root">
      <div ref={attachMount} className="game-canvas-wrap" />
      <div className="vignette" aria-hidden="true" />

      {debugOpen ? <DebugOverlay debug={debug} passiveCount={passiveCount} hostileCount={hostileCount} daylightPercent={daylightPercent} /> : null}

      {showClickHint ? <div className="click-hint">Double-click to play</div> : null}

      <BossHealthBar boss={boss} />

      <ActiveEffects effects={activeEffects} />

      {saveMessage && !paused ? (
        <div className="hud-toast" role="status">
          {saveMessage}
        </div>
      ) : null}

      <div ref={attachMinimap} className="minimap" data-testid="minimap" />

      <div className="hud-bottom">
        <StatusBars
          hearts={hearts}
          maxHearts={maxHearts}
          hunger={hunger}
          maxHunger={maxHunger}
          armorPoints={armorPoints}
          oxygen={oxygen}
          maxOxygen={maxOxygen}
        />
        <XpBar level={xpLevel} progress={xpProgress} />
        <Hotbar inventory={inventory} selectedSlot={selectedSlot} hotbarSlots={hotbarSlots} onSelectSlot={setSelectedSlot} />
      </div>

      {inventoryOpen || paused ? <div className="menu-backdrop" /> : null}

      {inventoryOpen ? (
        <InventoryPanel
          inventory={inventory}
          equippedArmor={equippedArmor}
          selectedHotbarSlot={selectedSlot}
          hotbarSlots={hotbarSlots}
          recipes={recipes}
          craftingStation={craftingStation}
          gameMode={gameMode}
          container={container}
          xpLevel={xpLevel}
          enchantCost={ENCHANT_COST_LEVELS}
          canCraft={canCraft}
          onSwapSlots={swapInventorySlots}
          onMoveStack={moveStack}
          onToggleEquipArmor={toggleEquipArmor}
          onCraft={craft}
          onEnchant={enchant}
          onGiveItem={giveCreativeItem}
        />
      ) : null}

      {paused ? (
        <PauseMenu
          saveMessage={saveMessage}
          audioSettings={audioSettings}
          onAudioSettingsChange={updateAudioSettings}
          skinId={skinId}
          onSkinChange={updateSkin}
          onBack={resumeNow}
          onSave={saveNow}
          onLoad={loadNow}
          onReset={resetNow}
          onQuitToWorlds={quitToWorlds}
        />
      ) : null}

      <DeathScreen seconds={respawnSeconds} onRespawn={respawnNow} />

      <VictoryScreen show={victory} onDismiss={dismissVictory} />

      <SleepOverlay sleeping={sleeping} />

      <div className="crosshair" />
      <div className={capsActive ? "caps-indicator on" : "caps-indicator"}>CapsLock {capsActive ? "ON (Sprint)" : "OFF"}</div>
    </div>
  );
}

"use client";

import { useEffect } from "react";
import ActiveEffects from "@/components/game/ActiveEffects";
import BossHealthBar from "@/components/game/BossHealthBar";
import DeathScreen from "@/components/game/DeathScreen";
import DebugOverlay from "@/components/game/DebugOverlay";
import Hotbar from "@/components/game/Hotbar";
import InventoryPanel from "@/components/game/InventoryPanel";
import PauseMenu from "@/components/game/PauseMenu";
import SleepOverlay from "@/components/game/SleepOverlay";
import StatusBars from "@/components/game/StatusBars";
import VictoryScreen from "@/components/game/VictoryScreen";
import XpBar from "@/components/game/XpBar";
import { ENCHANT_COST_LEVELS } from "@/lib/game/config";
import type { Profile } from "@/lib/game/profiles";
import { useMinecraftGame } from "@/lib/game/useMinecraftGame";
import { takesDamage, usesInventory } from "@/lib/game/gameModes";
import type { WorldMeta } from "@/lib/game/worlds";
import { installUiTiles } from "@/lib/ui/chromeTiles";

type MinecraftGameProps = {
  world: WorldMeta;
  profile: Profile;
  onQuitToWorlds: () => void;
  onReloadWorld: () => void;
};

export default function MinecraftGame({ world, profile, onQuitToWorlds, onReloadWorld }: MinecraftGameProps) {
  const {
    attachMount,
    attachMinimap,
    locked,
    rendererError,
    gameMode,
    giveCreativeItem,
    selectedSlot,
    setSelectedSlot,
    capsActive,
    inventoryOpen,
    inventory,
    equippedArmor,
    armorPoints,
    hearts,
    hunger,
    oxygen,
    daylightPercent,
    passiveCount,
    hostileCount,
    respawnSeconds,
    paused,
    sleeping,
    craftingStation,
    container,
    boss,
    victory,
    activeEffects,
    xpLevel,
    xpProgress,
    debugOpen,
    debug,
    saveMessage,
    audioSettings,
    updateAudioSettings,
    skinId,
    updateSkin,
    hotbarSlots,
    recipes,
    maxHearts,
    maxHunger,
    maxOxygen,
    canCraft,
    craft,
    enchant,
    swapInventorySlots,
    moveStack,
    toggleEquipArmor,
    resumeNow,
    respawnNow,
    dismissVictory,
    saveNow,
    loadNow,
    resetNow,
    quitToWorlds
  } = useMinecraftGame({ world, profile, onQuitToWorlds, onReloadWorld });

  useEffect(() => {
    installUiTiles();
  }, []);

  if (rendererError) {
    return (
      <div className="game-root">
        <div className="renderer-error">
          <h2>Could not start the 3D renderer</h2>
          <p>WebGL appears to be unavailable in this browser ({rendererError}).</p>
          <p>Try enabling hardware acceleration or switching browsers, then reload.</p>
        </div>
      </div>
    );
  }

  const showClickHint = !locked && !paused && !inventoryOpen && respawnSeconds === 0;

  return (
    <div className="game-root">
      <div ref={attachMount} className="game-canvas-wrap" />
      <div className="vignette" aria-hidden="true" />

      {debugOpen ? <DebugOverlay debug={debug} passiveCount={passiveCount} hostileCount={hostileCount} daylightPercent={daylightPercent} /> : null}

      {showClickHint ? <div className="click-hint">Double-click to play</div> : null}

      <BossHealthBar boss={boss} />

      <ActiveEffects effects={activeEffects} />

      {saveMessage && !paused ? (
        <div className="hud-toast" role="status">
          {saveMessage}
        </div>
      ) : null}

      <div ref={attachMinimap} className="minimap" data-testid="minimap" />

      <div className="hud-bottom">
        <StatusBars
          hearts={hearts}
          maxHearts={maxHearts}
          hunger={hunger}
          maxHunger={maxHunger}
          armorPoints={armorPoints}
          oxygen={oxygen}
          maxOxygen={maxOxygen}
        />
        <XpBar level={xpLevel} progress={xpProgress} />
        <Hotbar inventory={inventory} selectedSlot={selectedSlot} hotbarSlots={hotbarSlots} onSelectSlot={setSelectedSlot} />
      </div>

      {inventoryOpen || paused ? <div className="menu-backdrop" /> : null}

      {inventoryOpen ? (
        <InventoryPanel
          inventory={inventory}
          equippedArmor={equippedArmor}
          selectedHotbarSlot={selectedSlot}
          hotbarSlots={hotbarSlots}
          recipes={recipes}
          craftingStation={craftingStation}
          gameMode={gameMode}
          container={container}
          xpLevel={xpLevel}
          enchantCost={ENCHANT_COST_LEVELS}
          canCraft={canCraft}
          onSwapSlots={swapInventorySlots}
          onMoveStack={moveStack}
          onToggleEquipArmor={toggleEquipArmor}
          onCraft={craft}
          onEnchant={enchant}
          onGiveItem={giveCreativeItem}
        />
      ) : null}

      {paused ? (
        <PauseMenu
          saveMessage={saveMessage}
          audioSettings={audioSettings}
          onAudioSettingsChange={updateAudioSettings}
          skinId={skinId}
          onSkinChange={updateSkin}
          onBack={resumeNow}
          onSave={saveNow}
          onLoad={loadNow}
          onReset={resetNow}
          onQuitToWorlds={quitToWorlds}
        />
      ) : null}

      <DeathScreen seconds={respawnSeconds} onRespawn={respawnNow} />

      <VictoryScreen show={victory} onDismiss={dismissVictory} />

      <SleepOverlay sleeping={sleeping} />

      <div className="crosshair" />
      <div className={capsActive ? "caps-indicator on" : "caps-indicator"}>CapsLock {capsActive ? "ON (Sprint)" : "OFF"}</div>
    </div>
  );
}

