91	  gameMode?: GameMode;
92	  /** Randomness source for mob spawning/AI — injectable for deterministic tests. */
93	  rng?: () => number;
94	  /** World dimensions override for fast headless tests. */
95	  worldSize?: { x: number; y: number; z: number };
96	};
97	
98	/**
99	 * The framework-agnostic game core. Owns all simulation state, advances it in
100	 * step(), and accepts player intents through dispatch(). No React, no DOM, no
101	 * rendering — the renderer reads state, the React shell subscribes to
102	 * snapshots via subscribe()/getSnapshot() (useSyncExternalStore compatible).
103	 */
104	export class GameEngine {
105	  readonly state: GameState;
