115	  // The effects HUD projection is rebuilt only when its content (ids / rounded
116	  // seconds) changes, so the snapshot ref stays stable frame-to-frame and the
117	  // countdown re-renders at most ~once per second instead of every frame.
118	  private lastEffectsKey = "";
