126	    // A restored save's own type wins (the block-diffs were recorded against it);
127	    // a fresh world takes the requested type, defaulting to "default".
128	    this.worldType = save?.worldType ?? options.worldType ?? "default";
129	    const size = options.worldSize ?? { x: WORLD_SIZE_X, y: WORLD_SIZE_Y, z: WORLD_SIZE_Z };
