  --mc-tile-dirt: none;
  --mc-tile-stone: none;
  --mc-tile-panel: none;
  --mc-tile-well: none;
  --mc-tile-button: none;
  /* Strength of the always-on screen-edge vignette (fed into rgba alpha). */
  --mc-vignette: 0.28;
}
```

