.pause-modes {
  margin-bottom: 6px;
}

.pause-modes-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-top: 4px;
}

.mode-option[aria-pressed="true"] {
  border-color: #f0be3c;
  outline: 1px solid rgba(240, 190, 60, 0.6);
}

.mc-slider {
  appearance: none;
  width: 100%;
  height: 18px;
  margin: 0;
  background: var(--mc-tile-button), var(--mc-button);
  border-style: solid;
  border-width: 2px;
  border-color: #2c2c2c #a8a8a8 #a8a8a8 #2c2c2c;
  outline: 2px solid rgba(0, 0, 0, 0.85);
  cursor: pointer;
}

.mc-slider:focus-visible {
  background: var(--mc-button-hover);
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.mc-slider::-webkit-slider-thumb {
  appearance: none;
  width: 12px;
  height: 18px;
  background: var(--mc-button-hover);
  border-style: solid;
  border-width: 2px;
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.mc-slider::-moz-range-thumb {
  width: 12px;
  height: 18px;
  border-radius: 0;
  background: var(--mc-button-hover);
  border-style: solid;
  border-width: 2px;
  border-color: #c3cbe5 #34394d #34394d #c3cbe5;
}

.pause-save-message {
  text-align: center;
  color: #aef79f;
  font-size: 13px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
}

.pause-controls {
  margin-top: 12px;
  padding: 10px 12px;
  background: var(--mc-tile-dirt), rgba(20, 14, 8, 0.9);
  outline: 2px solid rgba(0, 0, 0, 0.85);
  display: grid;
  gap: 3px;
}

.pause-controls-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  color: #d4d4d4;
  font-size: 11px;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.7);
}

.pause-controls-row span:last-child {
  color: #f4f4f4;
  font-weight: 700;
}

.debug-overlay {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 5;
  display: grid;
  gap: 2px;
  justify-items: start;
  pointer-events: none;
  user-select: none;
}

.debug-line {
  background: rgba(16, 16, 16, 0.45);
  color: #e8e8e8;
  font-family: var(--mc-font-mono);
  font-size: 12px;
  line-height: 1.35;
  padding: 1px 5px;
  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.7);
  white-space: pre;
}

.click-hint {
  position: absolute;
  left: 50%;
  top: 38%;
  transform: translateX(-50%);
  z-index: 3;
  color: var(--mc-text-light);
  font-size: 15px;
  font-weight: 700;
  text-shadow: var(--mc-text-shadow);
  background: rgba(16, 16, 16, 0.45);
  padding: 6px 14px;
  outline: 2px solid rgba(0, 0, 0, 0.6);
  pointer-events: none;
  user-select: none;
  animation: click-hint-pulse 2.4s ease-in-out infinite;
}

@keyframes click-hint-pulse {
  0%,
  100% {
    opacity: 0.95;
  }
  50% {
    opacity: 0.55;
  }
}

/* Transient in-game toast (item pickups, sleep-denied notices) — sits just
   above the hotbar, like Minecraft's held-item name popup. */
.hud-toast {
  position: absolute;
  left: 50%;
  bottom: 96px;
  transform: translateX(-50%);
  z-index: 5;
  color: var(--mc-text-light);
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  text-shadow: var(--mc-text-shadow);
  background: rgba(16, 16, 16, 0.5);
  padding: 5px 12px;
  outline: 2px solid rgba(0, 0, 0, 0.55);
  pointer-events: none;
  user-select: none;
}

.renderer-error {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  max-width: min(92vw, 460px);
  background: var(--mc-tile-panel), var(--mc-panel);
  border-style: solid;
  border-width: 3px;
  border-color: var(--mc-bevel-light) var(--mc-bevel-dark) var(--mc-bevel-dark) var(--mc-bevel-light);
  color: var(--mc-text);
  padding: 18px 22px;
  text-align: center;
}

